        try { recognition.start() } catch (_) {}
      }
    }

    recognition.onend = () => {
      if (candidateRecording) {
        try { recognition.start() } catch (_) {}
      }
    }

    try {
      recognition.start()
      mockRecognitionRef.current = recognition
    } catch (_) {}
  }

