    if (aiAudioRef.current) {
      aiAudioRef.current.pause()
      aiAudioRef.current = null
    }
    stopVoiceRecording()
    stopMockSpeechRecognition()
    // Only stop tracks if they're NOT from the camera stream (avoid killing camera audio)
